        fn from_bytes_start(
            helper: &mut DeserializeHelper,
            bytes_start: &BytesStart<'_>,
        ) -> Result<Self, Error> {
            let mut style: Option<super::TgAttStyleType> = None;
            for attrib in helper.filter_xmlns_attributes(bytes_start) {
                let attrib = attrib?;
                if matches!(
                    helper.resolve_local_name(attrib.key, &super::NS_UNNAMED_5),
                    Some(b"style")
                ) {
                    helper.read_attrib(&mut style, b"style", &attrib.value)?;
                } else {
                    helper.raise_unexpected_attrib_checked(&attrib)?;
                }
            }
            Ok(Self {
                style: style,
                content: Vec::new(),
                state__: Box::new(TgolTypeDeserializerState::Init__),
            })
        }
